Res_Elv = (await d3.csv("https://data.coloradoriveratlas.org/ReservoirData/Reservoir_Elevation.csv")).map(d =&gt; ({
  ...d,
  Date: new Date(d.Date + "T00:00:00")
})).filter(d =&gt; d.Type === "Recorded")
render_date = d3.max(Res_Elv, d =&gt; d.Date).toLocaleDateString("en-US", {
  month: "long",
  day: "numeric",
  year: "numeric"
})
















